function generate(rand, size) {
  const names = ['Umbrella', 'SleepingBag', 'Tent', 'Lantern', 'Compass', 'Kayak'];
  const count = size === 'small' ? Math.floor(rand() * 7) : 1500 + Math.floor(rand() * 500);
  const figure = () => Math.floor(rand() * (size === 'small' ? 1000 : 100000));
  const report = [];
  for (let i = 0; i < count; i++) {
    const product = size === 'small' ? names[Math.floor(rand() * names.length)] : `${names[i % names.length]}${i}`;
    report.push([product, figure(), figure(), figure(), figure()]);
  }
  return [{ report }];
}
